<?php
/**
 * Antalya POS Menu Item Delete Handler
 *
 * @package Antalya_POS
 * @since 6.4
 */

if (!defined('ABSPATH')) {
    exit;
}

if (isset($_GET['del_item'])) {
    if (!current_user_can('manage_options')) {
        wp_die(esc_html__('You do not have sufficient permissions to perform this action.', 'antalya-pos'));
    }

    $item_id = intval($_GET['del_item']);
    if ($item_id > 0) {
        // Verify CSRF nonce generated by wp_nonce_url() in item-list.php & item-view.php
        check_admin_referer('rtpos_delete_item_' . $item_id);

        global $wpdb;
        $t_menu    = $wpdb->prefix . 'rtpos_menu';
        $svg_check = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>';

        $deleted = $wpdb->delete(
            $t_menu,
            ['id' => $item_id],
            ['%d']
        );

        if ($deleted !== false) {
            echo '<div class="apos-alert itm-alert-flex">' . $svg_check . '<span>' . sprintf(
                /* translators: %d: item ID */
                esc_html__('Dish #%d deleted successfully!', 'antalya-pos'),
                $item_id
            ) . '</span></div>';
        }
    }
}